ruleToc.chapterList:
@js:
(function(){
  var out = [];
  try {
    var d = JSON.parse(result);
    var arr = d.chapters || [];
    for (var i=0;i<arr.length;i++){
      var it = arr[i] || {};
      var id = String(it.id || '');
      if (!id) continue;
      out.push({
        name: it.title || '',
        url: id
      });
    }
  } catch(e) {
    out = [];
  }
  return out;
})()
